import { readFile, writeFile } from "node:fs/promises";
async function patch(path, from, to) { const text = await readFile(path, "utf8"); if (!text.includes(from)) throw new Error(`Missing anchor: ${path}`); await writeFile(path, text.replace(from, to)); }
await patch("public/monster-master.html", '  <link rel="stylesheet" href="/monster-master-trainer.css">', '  <link rel="stylesheet" href="/monster-master-trainer.css">\n  <link rel="stylesheet" href="/monster-master-roster-builder.css">');
await patch("public/monster-master.html", '  <script type="module" src="/monster-master-trainer-asset.js"></script>\n  <script type="module" src="/auth-launcher.js" data-entry="/monster-master-app.js"></script>', '  <script src="/monster-master-roster-builder.js"></script>\n  <script type="module" src="/monster-master-trainer-asset.js"></script>\n  <script type="module" src="/auth-launcher.js" data-entry="/monster-master-app.js"></script>');
await patch("public/monster-master-app.js", '  const team = unit.id.startsWith("alpha-") ? "Alpha" : "Beta";\n  return `${team} ${roleLabel(unit.role)}`;', '  const team = unit.id.startsWith("alpha-") ? "Alpha" : "Beta";\n  const contentLabel = window.gameFrameMonsterMasterRosterBuilder?.labelForContentId?.(unit.contentId);\n  return `${team} ${contentLabel ?? roleLabel(unit.role)}`;');
await patch("public/monster-master-app.js", '  challengeBot.disabled = busy;\n  createHumanMatch.disabled = busy;', '  const rosterReady = Boolean(window.gameFrameMonsterMasterRosterBuilder?.getSelection?.());\n  challengeBot.disabled = busy || !rosterReady;\n  createHumanMatch.disabled = busy || !rosterReady;');
await patch("public/monster-master-app.js", '  setBusy(true);\n  try {\n    render(await request("/api/matches", {\n      method: "POST",\n      body: JSON.stringify({ gameId, playerIds: [playerId, opponentId] }),\n    }));', '  const monsterMasterArena = window.gameFrameMonsterMasterRosterBuilder?.getSelection?.();\n  if (!monsterMasterArena) {\n    showError("Choose one Master and three monsters before starting a battle.");\n    lobbyMessage.textContent = "Choose an Arena loadout.";\n    return;\n  }\n  setBusy(true);\n  try {\n    render(await request("/api/matches", {\n      method: "POST",\n      body: JSON.stringify({ gameId, playerIds: [playerId, opponentId], monsterMasterArena }),\n    }));');
